import argparse,csv,json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from nfl_v2.shared_subgroups import load,write,sha

def run(public_root):
 root=Path(public_root);p=load(root/'FROZEN_PROTOCOL.json');scores=load(root/'SCORES.json');pairs=load(root/'PAIRED_COMPARISONS.json')['rows'];by={r['record_id']:r for r in scores};output=[]
 for c in pairs:
  r=by[c['source_record_id']];u=c.get('uncertainty')or{};ci=u.get('week_interval');output.append(dict(season=r['season'],recipe_group=r['recipe_group'],target=r['target'],population=r['population'],cohort_id=r['cohort_id'],fallback_view=r['fallback_view'],procedure_id=r['procedure_id'],history_regime=r['history_regime'],product_id=r['product_id'],reference_view=c['reference_view'],reference_procedure_id=c.get('comparator_procedure_id'),reference_history_regime=c.get('comparator_history_regime'),reference_product_id=c.get('comparator_product_id'),metric=c['metric'],candidate_error=c.get('candidate_error'),reference_error=c.get('comparator_error'),error_delta=c.get('absolute_error_delta'),relative_error_delta=c.get('relative_error_delta'),paired_n=c['paired_n'],forecast_rows=r['forecast_rows'],scored_n=r['n'],fallback_rows=r['fallback_rows'],week_clusters=u.get('week_clusters'),week_ci_low=None if ci is None else ci[0],week_ci_high=None if ci is None else ci[1],membership_sha256=c.get('membership_sha256'),source_record_id=r['record_id'],source_score_sha256=sha(root/'SCORES.json'),status=c['status']))
 with(root/'TOP_PLAYER_AND_ROLE_SCORECARD.csv').open('x',newline='')as f:
  w=csv.DictWriter(f,fieldnames=list(output[0]));w.writeheader();w.writerows(output)
 def find(group,target,cohort,ref,view='full_system'):
  return next((r for r in output if(r['recipe_group'],r['target'],r['population'],r['cohort_id'],r['reference_view'],r['fallback_view'])==(group,target,'primary',cohort,ref,view)),None)
 def delta(group,target,cohort,ref,view='full_system'):
  r=find(group,target,cohort,ref,view);return '—'if r is None or r['error_delta']is None else f"{r['error_delta']:+.4f} ({r['paired_n']})"
 groups=sorted({r['recipe_group']for r in scores});targets=sorted({r['target']for r in scores});refs=list(dict.fromkeys(c['reference_view']for c in pairs));primary='same_season_strongest_control'if p['mode']=='season'else'fixed_strong_control';second='fixed_2026_control'if p['mode']=='season'else'same_leaf_control'
 lines=[f"# {p['evaluation_season']}: compact shared subgroup comparison",'',
'These are retained-point replays, with zero fits, new forecasts or current 2026 Week 8 outcomes. Every comparison uses exactly the same frozen player-game-category membership for candidate and control. Numeric losses are MAE; anytime TD uses Brier. Negative changes favor the candidate. Parentheses give paired supported rows. References and candidate history/product choices were fixed from already exposed full-primary records before this compact replay; they are not selected within subgroups or presented as an earlier live routing policy.','',
'**Website improvement is unestablished.** The separate [server-retained R0 reference](../server-retained-R0-v1/RUN_RECEIPT.json) wins eight of ten numeric categories on a matched 13-game 2026 Week 7 panel (passing-yard MAE 58.18724 versus fixed V2 72.39038). Retention by October 23 at 17:49:53 UTC precedes the later games’ deadlines, but does not establish internal capture time, provider input vintage or today’s website method. That smaller panel is distinct from these full-season/reconstructed comparisons.']
 for group in groups:
  lines+=['',f'## {group}','',
'| Target | Full candidate error | Δ strong control: full | Top 10 | Top 15 | Top 20 | High prior band | Δ second reference: full |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
  for target in targets:
   r=find(group,target,'all',primary);err='—'if r is None or r['candidate_error']is None else f"{r['candidate_error']:.4f}";band='score_history_high'if target=='nick-chart-ppr-v1'else'workload_high';lines.append('| '+' | '.join([target,err,delta(group,target,'all',primary),delta(group,target,'top10',primary),delta(group,target,'top15',primary),delta(group,target,'top20',primary),delta(group,target,band,primary),delta(group,target,'all',second)])+' |')
  lines+=['','| Target | Own-learned full Δ | Candidate + both controls learned full Δ | Common-learned top 20 Δ |','| --- | ---: | ---: | ---: |']
  for target in targets:lines.append('| '+' | '.join([target,delta(group,target,'all',primary,'own_learned_only'),delta(group,target,'all',primary,'selected_candidate_and_controls_common_learned_overlap'),delta(group,target,'top20',primary,'selected_candidate_and_controls_common_learned_overlap')])+' |')
 lines+=['','The compact [CSV scorecard](TOP_PLAYER_AND_ROLE_SCORECARD.csv) retains full, own-learned, joint candidate-plus-two-control learned and fallback-only views; top 10/15/20; disjoint ranks 1–10, 11–15, 16–20 and remainder; unranked players; all low/middle/high/zero/unknown bands; and primary/extended populations. Unknown labels remain in forecast coverage. Chart median tolerances use the exact signed 0.02 grid. Mean forecasts are never rounded. This projects displayed points; genuine-mean and proper-law rankings remain in their original full-method artifacts.','',
'Football ranks use earlier attempts, carries, targets or carries plus targets. Chart ranks use earlier signed chart points, not workload. These selectors are common to all competitors but arise within a retrospective statistical-row/physical-participation universe. They do not authenticate historical ex-ante eligibility or offered props. The inherited seven-day availability assumption and common older selector memory remain disclosed.','',
'Whole-week paired bootstrap intervals use 500 fixed-seed replicates when at least eight observed weeks exist; seven-week current panels retain the insufficient-cluster flag and game sensitivity. Intervals do not correct procedure selection, subgroup multiplicity or earlier research exposure. The joint learned mask here is the selected candidate and its two registered controls, not a three-history overlap or the broader v2 all-family/all-policy mask.','',
'[Canonical scores](SCORES.json) · [Paired references](PAIRED_COMPARISONS.json) · [Source-bound protocol](FROZEN_PROTOCOL.json) · [Coverage/resources](RUN_RECEIPT.json)']
 if p['mode']=='season':lines+=['','This compact v3 corrects empirical output aliases explicitly (empirical_mean → mean; empirical_lower_median → lower_median) while preserving functional identity. It does not overwrite or silently certify the broader v2 comparison matrix or its mask. The fixed 2026 recipe/reference view tests persistence; the strongest observed same-season full-primary reference supplies a stronger practical benchmark. Both are exposed retrospective comparisons.']
 else:lines+=['','D1/D2 use the actual frozen four-observed-position-group recipe. See the [window-definition finding](../qualified-defense-information-v1/WINDOW_DEFINITION_FINDING.md): six entirely absent TE groups are not calendar-padded, although missing targets within observed groups consume slots. No model, forecast, source label or fitted parameter is changed by this subgroup scoring.']
 (root/'README.md').write_text('\n'.join(lines)+'\n');write(root/'COMPACT_REPORT_BINDING.json',dict(source_score_sha256=sha(root/'SCORES.json'),source_pair_sha256=sha(root/'PAIRED_COMPARISONS.json'),source_protocol_sha256=sha(root/'FROZEN_PROTOCOL.json'),code_sha256=sha(__file__),csv_rows=len(output),new_univariate_views=0,new_fits=0,new_forecasts=0,current2026_week8_outcomes_read=0));return dict(compact_rows=len(output),groups=groups,targets=len(targets))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--public-root',type=Path,required=True);print(json.dumps(run(**vars(p.parse_args()))))
